choose.when:
WITH RECURSIVE org_tree AS ( -- 1단계: 검색 조건에 매칭되는 조직들 (시작점들) SELECT ognz_cd, /* 조직 코드 */ ognz_nm, /* 조직 명 */ anct_ognz_cd AS up_ognz_cd, /* 상위 조직 코드 */ ognz_lvl, /* 조직 레벨 */ sort_seq AS sort_sn, /* 정렬 일련번호 */ use_yn, /* 사용 여부 */ 1 as search_match /* 검색 매칭 표시 */ FROM cdm_own.ognz WHERE (ognz_cd LIKE '%' || #{ognzCdOrNm} || '%' OR ognz_nm LIKE '%' || #{ognzCdOrNm} || '%')
AND use_yn = #{useYn}
UNION ALL
-- 2단계: 검색된 조직들의 하위 조직들 (재귀 조회) SELECT c.ognz_cd, c.ognz_nm, c.anct_ognz_cd AS up_ognz_cd, c.ognz_lvl, c.sort_seq AS sort_sn, c.use_yn, 0 as search_match /* 하위 조직 표시 */ FROM cdm_own.ognz c INNER JOIN org_tree p ON c.anct_ognz_cd = p.ognz_cd
WHERE c.use_yn = #{useYn}
) SELECT ognz_cd, ognz_nm, up_ognz_cd, ognz_lvl, sort_sn FROM org_tree ORDER BY search_match DESC, ognz_lvl, sort_sn, ognz_cd
